<?php require __DIR__.'/../includes/functions.php'; require_login('admin'); if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf(); if(isset($_POST['create_student'])){$name=trim($_POST['name']??'');$mobile=trim($_POST['mobile']??'');$password=$_POST['password']??'';if($name===''||$mobile===''||strlen($password)<6){flash('نام، موبایل و رمز حداقل ۶ کاراکتری را وارد کنید.');}else{try{$h=password_hash($password,PASSWORD_DEFAULT);db()->prepare("INSERT INTO users(mobile,password_hash,role,name) VALUES(?,?,'student',?)")->execute([$mobile,$h,$name]);flash('کاربر جدید ساخته شد؛ اطلاعات ورود را به دانش‌آموز بدهید.');}catch(PDOException $e){flash($e->getCode()==='23000'?'این شماره موبایل قبلاً ثبت شده است.':'خطا در ساخت کاربر.');}}} elseif(isset($_POST['flag'])) db()->prepare('UPDATE student_profiles SET emergency_flag=? WHERE user_id=?')->execute([$_POST['flag']==='1'?1:0,(int)$_POST['student_id']]); elseif(isset($_POST['body'])){db()->prepare("INSERT INTO messages(student_id,sender_role,body) VALUES(?, 'admin', ?)")->execute([(int)$_POST['student_id'],trim($_POST['body'])]);flash('پیام ارسال شد.');} redirect('/admin/index.php');} $students=db()->query("SELECT u.id,u.name,u.mobile,p.parent_name,p.parent_phone,p.consent,p.emergency_flag,p.updated_at,(SELECT COUNT(*) FROM messages m WHERE m.student_id=u.id AND m.sender_role='student' AND m.is_read=0) unread FROM users u LEFT JOIN student_profiles p ON p.user_id=u.id WHERE u.role='student' ORDER BY p.emergency_flag DESC,u.created_at DESC"); layout_start('پنل مدیریت'); ?><div class="page-head"><div><p class="eyebrow">پنل مدیریت</p><h1>دانش‌آموزان</h1></div><span class="badge"><?=e($students->rowCount())?> نفر</span></div><div class="card create-user"><h2>تعریف دانش‌آموز جدید</h2><p class="muted">این اطلاعات ورود را شخصاً و از مسیر امن در اختیار دانش‌آموز قرار دهید.</p><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="create_student" value="1"><label>نام و نام خانوادگی<input name="name" required></label><label>شماره موبایل<input name="mobile" inputmode="tel" required></label><label>رمز اولیه<input type="password" name="password" minlength="6" required></label><div><button class="button" type="submit">ساخت کاربر</button></div></form></div><div class="card table-wrap"><table><thead><tr><th>نام</th><th>موبایل</th><th>والد</th><th>رضایت</th><th>وضعیت</th><th>اقدام</th></tr></thead><tbody><?php while($s=$students->fetch()):?><tr class="<?=!empty($s['emergency_flag'])?'urgent':''?>"><td><strong><?=e($s['name'])?></strong><?php if($s['unread']):?><span class="badge">پیام جدید</span><?php endif;?></td><td><?=e($s['mobile'])?></td><td><?=e($s['parent_name']??'—')?> <small><?=e($s['parent_phone']??'')?></small></td><td><?=!empty($s['consent'])?'تأیید شده':'تکمیل نشده'?></td><td><?=!empty($s['emergency_flag'])?'نیازمند پیگیری':'عادی'?></td><td><a href="<?=e(url('/admin/student.php?id='.$s['id']))?>">مشاهده / پیام</a><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="student_id" value="<?=$s['id']?>"><button name="flag" value="<?=empty($s['emergency_flag'])?1:0?>"><?=empty($s['emergency_flag'])?'علامت اضطراری':'رفع علامت'?></button></form></td></tr><?php endwhile;?></tbody></table></div><?php layout_end(); ?>
